// Generate src/lib/api-types.gen.ts from the committed backend OpenAPI document.
//   node scripts/gen-api-types.mjs           rewrite the generated file
//   node scripts/gen-api-types.mjs --check   fail when the committed file is stale
// The check runs before `tsc -b`, so a schema change that skips regeneration breaks the build.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const SPEC = new URL('../../backend/openapi.json', import.meta.url)
const OUT = new URL('../src/lib/api-types.gen.ts', import.meta.url)
const HEADER = [
  '// Generated by scripts/gen-api-types.mjs from apps/backend/openapi.json — do not edit.',
  '// Regenerate with `python tools/export_openapi.py` then `npm run gen:api-types`.',
  '',
].join('\n')

const pascal = (name) =>
  name
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean)
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('') || 'Schema'

const inlineObject = (schema) => {
  const required = new Set(schema.required ?? [])
  const fields = Object.entries(schema.properties).map(
    ([key, value]) => `${key}${required.has(key) ? '' : '?'}: ${typeOf(value)}`,
  )
  return fields.length ? `{ ${fields.join('; ')} }` : 'Record<string, unknown>'
}

function typeOf(schema) {
  if (!schema) return 'unknown'
  if (schema.$ref) return pascal(schema.$ref.split('/').pop())
  if (schema.enum) return schema.enum.map((value) => JSON.stringify(value)).join(' | ')
  const union = schema.anyOf ?? schema.oneOf
  if (union) return [...new Set(union.map(typeOf))].join(' | ')
  if (schema.allOf) return schema.allOf.map(typeOf).join(' & ')
  const types = Array.isArray(schema.type) ? schema.type : schema.type ? [schema.type] : []
  if (types.length > 1) return [...new Set(types.map((type) => typeOf({ ...schema, type })))].join(' | ')
  switch (types[0]) {
    case 'string':
      return 'string'
    case 'integer':
    case 'number':
      return 'number'
    case 'boolean':
      return 'boolean'
    case 'null':
      return 'null'
    case 'array': {
      const item = typeOf(schema.items)
      return / [|&] /.test(item) ? `(${item})[]` : `${item}[]`
    }
    case 'object':
      if (schema.properties) return inlineObject(schema)
      if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
        return `Record<string, ${typeOf(schema.additionalProperties)}>`
      }
      return 'Record<string, unknown>'
    default:
      return schema.properties ? inlineObject(schema) : 'unknown'
  }
}

function block(name, schema) {
  if (!schema.properties) return `export type ${name} = ${typeOf(schema)}`
  const required = new Set(schema.required ?? [])
  const fields = Object.entries(schema.properties).map(
    ([key, value]) => `  ${key}${required.has(key) ? '' : '?'}: ${typeOf(value)}`,
  )
  if (!fields.length) return `export type ${name} = Record<string, unknown>`
  return `export interface ${name} {\n${fields.join('\n')}\n}`
}

export function render(spec) {
  const schemas = spec?.components?.schemas ?? {}
  const seen = new Map()
  const blocks = Object.keys(schemas)
    .sort()
    .map((key) => {
      const name = pascal(key)
      if (seen.has(name)) throw new Error(`two schemas map to ${name}: ${seen.get(name)} and ${key}`)
      seen.set(name, key)
      return { name, text: block(name, schemas[key]) }
    })
    .sort((a, b) => a.name.localeCompare(b.name))
  return `${HEADER}\n${blocks.map((entry) => entry.text).join('\n\n')}\n`
}

function main() {
  const check = process.argv.includes('--check')
  if (check && !existsSync(SPEC)) {
    // The docker image builds apps/frontend alone, so the contract file is not in that context.
    // The same commit already passed this check in CI; only generation is impossible here.
    console.warn(`skip: ${fileURLToPath(SPEC)} is outside this build context`)
    return
  }
  const text = render(JSON.parse(readFileSync(SPEC, 'utf8')))
  if (!check) {
    writeFileSync(OUT, text)
    console.log(`wrote ${fileURLToPath(OUT)}`)
    return
  }
  if (readFileSync(OUT, 'utf8') === text) return
  console.error(
    `${fileURLToPath(OUT)} is stale: apps/backend/openapi.json changed.\n` +
      'Run `npm run gen:api-types` in apps/frontend and commit the result.',
  )
  process.exitCode = 1
}

const entry = process.argv[1] ? resolve(process.argv[1]).toLowerCase() : ''
if (entry === resolve(fileURLToPath(import.meta.url)).toLowerCase()) main()
